SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRY
BEGIN TRANSACTION;
IF OBJECT_ID(N'dbo.Sistema_Modulos',N'U') IS NULL OR OBJECT_ID(N'dbo.Sistema_ModulosMenus',N'U') IS NULL OR OBJECT_ID(N'dbo.Usuario_Modulos',N'U') IS NULL OR OBJECT_ID(N'dbo.Usuario_Acciones',N'U') IS NULL OR OBJECT_ID(N'dbo.Usuario_Roles',N'U') IS NULL OR OBJECT_ID(N'dbo.Usuario_PermisosRolModulo',N'U') IS NULL THROW 51200,'Faltan tablas canonicas de menu/RBAC.',1;
DECLARE @sm INT,@um INT,@ver INT,@padre INT,@centro INT;
SELECT @sm=ModuloID FROM dbo.Sistema_Modulos WHERE Codigo=N'BOS';
IF @sm IS NULL BEGIN INSERT dbo.Sistema_Modulos(Codigo,Nombre,Descripcion,Icono,Orden,EsPrincipal,EsSatelite,EsPortal,URLExterna,Activo,FechaCreacion) SELECT N'BOS',N'BOS',N'Business Operating System EDARSAHUB',N'Bot',ISNULL(MAX(Orden),0)+1,1,0,0,NULL,1,GETDATE() FROM dbo.Sistema_Modulos; SET @sm=CONVERT(INT,SCOPE_IDENTITY()); END;
IF NOT EXISTS(SELECT 1 FROM dbo.Usuario_Modulos WHERE CodigoModulo=N'BOS_AGENTES') INSERT dbo.Usuario_Modulos(CodigoModulo,NombreModulo,Descripcion,Icono,Ruta,Activo) VALUES(N'BOS_AGENTES',N'Agentes e IA',N'Gobierno de agentes BOS',N'Bot',N'/bos/agentes-ia',1);
SELECT @um=ModuloID FROM dbo.Usuario_Modulos WHERE CodigoModulo=N'BOS_AGENTES';
SELECT TOP(1) @ver=AccionID FROM dbo.Usuario_Acciones WHERE CodigoAccion=N'VER' AND Activo=1 ORDER BY AccionID;
IF @um IS NULL OR @ver IS NULL THROW 51201,'No fue posible resolver BOS_AGENTES/VER.',1;
INSERT dbo.Usuario_PermisosRolModulo(RolID,ModuloID,AccionID,Permitido,RestriccionPropietario,RestriccionSucursal,RequiereAutorizacion,Activo,FechaAlta,CreatedBy) SELECT r.RolID,@um,@ver,1,0,0,0,1,SYSDATETIME(),N'BOS_GATE6B' FROM dbo.Usuario_Roles r WHERE r.Activo=1 AND r.CodigoRol IN(N'SUPERADMIN',N'SUPERADMINISTRADOR',N'ADMIN',N'ADMINISTRADOR') AND NOT EXISTS(SELECT 1 FROM dbo.Usuario_PermisosRolModulo p WHERE p.RolID=r.RolID AND p.ModuloID=@um AND p.AccionID=@ver);
SELECT @padre=MenuID FROM dbo.Sistema_ModulosMenus WHERE Codigo=N'bos.agentes_ia';
IF @padre IS NULL BEGIN INSERT dbo.Sistema_ModulosMenus(ModuloID,MenuPadreID,Codigo,Nombre,Descripcion,Icono,Ruta,Orden,RequierePermiso,Activo,FechaCreacion) VALUES(@sm,NULL,N'bos.agentes_ia',N'Agentes e IA',N'Gobierno y operacion de agentes BOS',N'Bot',N'/bos/agentes-ia',10,N'BOS_AGENTES',1,GETDATE()); SET @padre=CONVERT(INT,SCOPE_IDENTITY()); END;
SELECT @centro=MenuID FROM dbo.Sistema_ModulosMenus WHERE Codigo=N'bos.centro_agentes';
IF @centro IS NULL INSERT dbo.Sistema_ModulosMenus(ModuloID,MenuPadreID,Codigo,Nombre,Descripcion,Icono,Ruta,Orden,RequierePermiso,Activo,FechaCreacion) VALUES(@sm,@padre,N'bos.centro_agentes',N'Centro de Agentes',N'Catalogo y estado de agentes BOS',N'Bot',N'/bos/agentes-ia/centro-agentes',20,N'BOS_AGENTES',1,GETDATE());
COMMIT TRANSACTION;
SELECT N'BOS_AGENTES_IA_MIGRATION_READY' AS resultado;
END TRY BEGIN CATCH IF @@TRANCOUNT>0 ROLLBACK TRANSACTION; THROW; END CATCH;

from __future__ import annotations
from dataclasses import dataclass
from typing import Mapping
from core.agent_capability_policy import BudgetRequest,DataClassification,PolicyContext,PolicyRequest,RiskLevel
from core.agent_execution_gate import authorize_external_research_execution
from core.agent_external_research_service import execute_external_research
from core.agent_runtime_activation import RuntimeEnvironment

class ModuleAgentReachError(ValueError): pass

@dataclass(frozen=True)
class ModuleExternalResearchRequest:
    request_id:str; module_code:str; permission:str; empresa_id:int; unidad_id:int; query:str; external_calls_budget:int=1
    def __post_init__(self):
        if not all(str(x).strip() for x in (self.request_id,self.module_code,self.permission,self.query)): raise ModuleAgentReachError('REQUIRED_FIELD_MISSING')
        if self.empresa_id<=0 or self.unidad_id<=0: raise ModuleAgentReachError('BUSINESS_SCOPE_INVALID')
        if self.external_calls_budget!=1: raise ModuleAgentReachError('EXTERNAL_CALL_BUDGET_MUST_EQUAL_ONE')

def _auth(req,auth:Mapping[str,object]):
    if not isinstance(auth,Mapping) or auth.get('allowed') is not True: raise ModuleAgentReachError('REQUESTER_RBAC_DENIED')
    if str(auth.get('module_code'))!=req.module_code or str(auth.get('permission'))!=req.permission: raise ModuleAgentReachError('REQUESTER_PERMISSION_MISMATCH')
    if int(auth.get('empresa_id') or 0)!=req.empresa_id or int(auth.get('unidad_id') or 0)!=req.unidad_id: raise ModuleAgentReachError('REQUESTER_BUSINESS_SCOPE_MISMATCH')

def authorize_module_external_research(req:ModuleExternalResearchRequest,auth:Mapping[str,object],context:PolicyContext):
    _auth(req,auth)
    scopes=frozenset({'external:web',f'empresa:{req.empresa_id}',f'unidad:{req.unidad_id}'})
    policy=PolicyRequest(capabilities=frozenset({'EXTERNAL_RESEARCH'}),scopes=scopes,risk=RiskLevel.R1,data_classification=DataClassification.PUBLIC,budgets=BudgetRequest(external_calls=1),external_egress=True,production_allowed=False,privilege_expansion=False,procedure='agent-reach-external-research')
    gate=authorize_external_research_execution(dict(auth),req.query,policy,context)
    return gate,policy

def execute_module_external_research(req:ModuleExternalResearchRequest,auth:Mapping[str,object],context:PolicyContext,versions_lock_path:str,*,environment=RuntimeEnvironment.DEVELOPMENT,timeout_seconds:int=20):
    gate,policy=authorize_module_external_research(req,auth,context)
    if not gate.allowed: raise ModuleAgentReachError(gate.reasons[0] if gate.reasons else 'EXECUTION_GATE_DENIED')
    return execute_external_research(dict(auth),req.query,policy,context,versions_lock_path,environment=environment,timeout_seconds=timeout_seconds)

from core.agent_capability_policy import PolicyContext
from .module_agent_reach_adapter import ModuleExternalResearchRequest,authorize_module_external_research

def authorize_marketing_public_research(*,request_id:str,empresa_id:int,unidad_id:int,query:str,requester_authorization:dict[str,object],context:PolicyContext):
    req=ModuleExternalResearchRequest(request_id,'MARKETING','MARKETING',empresa_id,unidad_id,query,1)
    return authorize_module_external_research(req,requester_authorization,context)

from pathlib import Path
import pytest
from core.agent_capability_policy import PolicyContext
from modules.agent_harness.module_agent_reach_adapter import ModuleAgentReachError,ModuleExternalResearchRequest,authorize_module_external_research

def ctx():
    c=frozenset({'EXTERNAL_RESEARCH'}); s=frozenset({'external:web','empresa:1','unidad:2'})
    return PolicyContext(c,c,c,c,s,s,s,s,{'external_calls':1})
def auth(allowed=True,unidad=2): return {'allowed':allowed,'module_code':'MARKETING','permission':'MARKETING','empresa_id':1,'unidad_id':unidad}
def test_gate6b_authorizes_public_r1_one_call():
    gate,policy=authorize_module_external_research(ModuleExternalResearchRequest('r1','MARKETING','MARKETING',1,2,'public trends'),auth(),ctx())
    assert gate.allowed and policy.budgets.external_calls==1 and policy.production_allowed is False
def test_gate6b_fails_closed():
    with pytest.raises(ModuleAgentReachError): authorize_module_external_research(ModuleExternalResearchRequest('r1','MARKETING','MARKETING',1,2,'q'),auth(False),ctx())
    with pytest.raises(ModuleAgentReachError): ModuleExternalResearchRequest('r1','MARKETING','MARKETING',1,2,'q',2)
def test_gate6b_no_direct_runtime_executor():
    text=Path('backend/modules/agent_harness/module_agent_reach_adapter.py').read_text()
    assert 'agent_reach_runtime_executor' not in text and 'agent_reach_public_search_executor' not in text and 'execute_external_research' in text

